package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct { // 01 LOAN-REC, 21 bytes
	LrAcct      string          // PIC X(6) @0 len=6
	LrPrincipal decimal.Decimal // PIC 9(7)V99 @6 len=9
	LrRate      decimal.Decimal // PIC 9(2)V99 @15 len=4
	LrYears     int64           // PIC 9(2) @19 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"                            // PIC X len=1 = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0) // PIC 9(9)V99 len=11 = 0
var WsTotal decimal.Decimal = decimal.NewFromInt(0)    // PIC 9(11)V99 len=13 = 0
var WsCount int64 = 0                                 // PIC 9(5) len=5 = 0
var WsPrinEd string                                   // PIC Z,ZZZ,ZZ9.99 len=12
var WsIntEd string                                    // PIC ZZZ,ZZZ,ZZ9.99 len=14
var WsTotalEd string                                  // PIC ZZ,ZZZ,ZZZ,ZZ9.99 len=17

var loanRec LoanRec
var loanScanner *bufio.Scanner

func countDigits(pic string) int {
	c := 0
	for _, ch := range pic {
		if ch == 'Z' || ch == '9' {
			c++
		}
	}
	return c
}

func int64Pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func decimalPow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func effectiveDecimal(val decimal.Decimal, intDigits, scale int) decimal.Decimal {
	if val.IsZero() {
		return decimal.NewFromInt(0)
	}
	neg := val.Sign() < 0
	abs := val.Abs()
	totalScaled := abs.Mul(decimalPow10(scale)).Truncate(0)
	pow10Total := decimalPow10(intDigits + scale)
	effScaled := totalScaled.Mod(pow10Total)
	res := effScaled.Shift(int32(-scale))
	if neg {
		res = res.Neg()
	}
	return res
}

func parseDecimalField(s string, scale int) decimal.Decimal {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		}
	}
	digits := b.String()
	if digits == "" {
		return decimal.NewFromInt(0)
	}
	d, _ := decimal.NewFromString(digits)
	return d.Shift(int32(-scale))
}

func parseIntField(s string) int64 {
	var b strings.Builder
	for _, ch := range s {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		}
	}
	digits := b.String()
	if digits == "" {
		return 0
	}
	n, _ := strconv.ParseInt(digits, 10, 64)
	return n
}

func formatWithPicture(val decimal.Decimal, picture string) string {
	// handle negative by formatting absolute and inserting minus
	if val.Sign() < 0 {
		pos := formatWithPicturePositive(val.Abs(), picture)
		// insert minus before first digit if possible
		runes := []rune(pos)
		firstDigit := -1
		for i, ch := range runes {
			if ch >= '0' && ch <= '9' {
				firstDigit = i
				break
			}
		}
		if firstDigit > 0 && runes[firstDigit-1] == ' ' {
			runes[firstDigit-1] = '-'
		} else if firstDigit == 0 {
			// no space, keep as is (overflow case)
		}
		return string(runes)
	}
	return formatWithPicturePositive(val, picture)
}

func formatWithPicturePositive(absVal decimal.Decimal, picture string) string {
	dotIdx := strings.Index(picture, ".")
	var intPic, fracPic string
	var scale int
	if dotIdx != -1 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
		scale = countDigits(fracPic)
	} else {
		intPic = picture
		fracPic = ""
		scale = 0
	}
	intDigits := countDigits(intPic)

	var intPartOrig int64
	var fracPart int64
	if scale > 0 {
		totalScaledDec := absVal.Shift(int32(scale)).Truncate(0)
		totalScaledInt := totalScaledDec.IntPart()
		powScale := int64Pow10(scale)
		intPartOrig = totalScaledInt / powScale
		fracPart = totalScaledInt % powScale
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		totalScaledDec := absVal.Truncate(0)
		intPartOrig = totalScaledDec.IntPart()
		fracPart = 0
	}
	effectiveInt := intPartOrig % int64Pow10(intDigits)
	effectiveIntStr := fmt.Sprintf("%0*d", intDigits, effectiveInt)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPart)
	}

	intOut := make([]rune, len(intPic))
	digitIdx := 0
	suppressed := true
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			d := effectiveIntStr[digitIdx]
			digitIdx++
			if ch == 'Z' && suppressed && d == '0' {
				intOut[i] = ' '
			} else {
				intOut[i] = rune(d)
				suppressed = false
			}
		} else if ch == ',' {
			if suppressed {
				intOut[i] = ' '
			} else {
				intOut[i] = ','
			}
		} else {
			intOut[i] = ch
		}
	}
	if scale > 0 {
		fracOut := make([]rune, len(fracPic))
		fIdx := 0
		for i, ch := range fracPic {
			if ch == 'Z' || ch == '9' {
				d := fracStr[fIdx]
				fIdx++
				fracOut[i] = rune(d)
			} else {
				fracOut[i] = ch
			}
		}
		return string(intOut) + "." + string(fracOut)
	}
	return string(intOut)
}

// Paragraph functions

func ReadPara() {
	if loanScanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !loanScanner.Scan() {
		if err := loanScanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "read error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		return
	}
	line := loanScanner.Text()
	if len(line) < 21 {
		line += strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	loanRec.LrAcct = line[0:6]
	loanRec.LrPrincipal = parseDecimalField(line[6:15], 2)
	loanRec.LrRate = parseDecimalField(line[15:19], 2)
	loanRec.LrYears = parseIntField(line[19:21])
	WsEofFlag = "N"
}

func ProcessPara() {
	prod := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(decimal.NewFromInt(loanRec.LrYears))
	div := prod.Shift(-2)
	rounded := div.Round(2)
	WsInterest = effectiveDecimal(rounded, 9, 2)

	WsTotal = effectiveDecimal(WsTotal.Add(WsInterest), 11, 2)

	WsCount = (WsCount + 1) % 100000

	WsPrinEd = formatWithPicture(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatWithPicture(WsInterest, "ZZZ,ZZZ,ZZ9.99")

	fmt.Printf("%s %s %s\n", loanRec.LrAcct, WsPrinEd, WsIntEd)

	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatWithPicture(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Printf("RECORDS: %s\n", countStr)
	fmt.Printf("TOTAL INTEREST: %s\n", WsTotalEd)
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			SummaryPara()
			return
		}
		fmt.Fprintf(os.Stderr, "open error: %v\n", err)
		os.Exit(1)
	}
	defer f.Close()
	loanScanner = bufio.NewScanner(f)
	// preserve behavior for long lines (Scanner default 64k is enough)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	SummaryPara()
}

func main() {
	MainPara()
}
